"""Five bounded oral-language connections, individually reviewed 2026-10-30."""
def append(T):
 T('informieren-lernplatz','Über Arbeitsmittel informieren','186271','39562 39568 39571','Ein gemeinsam betrachteter Arbeitsplatz mit vertrauten Arbeitsmitteln','einem Partner ein Arbeitsmittel anhand seiner Merkmale beschreiben','Ein vertrautes Arbeitsmittel benennen und beschreiben und seine Anordnung am eigenen Arbeitsplatz mit einem passenden Grund beurteilen.','Nur Arbeitsmittel im Rahmen der eigenen Lernumgebung. Die begründete Einschätzung gehört zum FSP-Operator Sich positionieren; Beschreiben allein genügt dafür nicht.',['186275'])
 T('erklaeren-arbeitsmittel','Den Umgang mit Arbeitsmitteln erklären','186271','39562 39568 39576','Der Umgang mit einem vertrauten Arbeitsmittel am eigenen Arbeitsplatz','eine einfache Erklärung zum Umgang mit dem Arbeitsmittel erproben und eine Rückfrage beantworten','Den Umgang mit einem vertrauten Arbeitsmittel erklären und den eigenen Umgang damit anhand eines vereinbarten Kriteriums begründet einschätzen.','Kein allgemeiner Anschluss für beliebige Erklärungen. Im FSP bleibt die Positionierung zur eigenen Lernumgebung Teil des Ziels.',['186276'])
 T('wortschatz-lage','Mit Lagewörtern Orientierung geben','186271','39794','Eine mündliche Suchanweisung zu einem Gegenstand im Klassenraum','passende Lagewörter in einer einfachen Suchanweisung erproben','Erarbeitete Lagebegriffe für eine neue räumliche Anordnung im Klassenraum selbst auswählen und so verwenden, dass ein Partner den gesuchten Gegenstand findet.','Nur räumlicher Wortschatz. FSP Anwenden verlangt eine neue Anordnung mit eigener Auswahl geeigneter Begriffe; GS Einblick verlangt keinen Routinenachweis.',['186278'])
 T('gespraechskultur-klasse','Respektvolle Gesprächsregeln kennen','186287','39605 39617','Eine vertraute Gesprächssituation in der Klasse mit einer Unterbrechung','eine gemeinsam erarbeitete Regel zum respektvollen Gespräch benennen und ein passendes Verhalten zeigen','Eine bekannte Regel des gemeinsamen Lernens nennen und ein dazu passendes respektvolles Gesprächsverhalten an einem vertrauten Beispiel wiedergeben.','Begrenzter Ausschnitt der Gesprächskultur. Wertschätzende Kommunikation und Konfliktlösung stehen im FSP in den Bemerkungen zu Regeln; keine umfassende selbstständige Konfliktlösung oder abgeschlossene Gesprächskultur behaupten.',['186292'])
 T('gespraechsregeln-entwickeln','Gemeinsame Gesprächsregeln formulieren','186287','40282 40286 40289 40291','Eine gemeinsam besprochene Gesprächssituation in der Klasse','an der Formulierung einer Gesprächsregel mitwirken und die vereinbarte Regel an einem bekannten Beispiel erläutern','Eine Gesprächsregel formulieren und das Verhalten in der besprochenen Klassensituation mit einem passenden Grund beurteilen.','Stufenübergreifend GS1/2 zu FSP3/4. Regeln formulieren und Verhalten einschätzen sind explizite FSP-Inhalte; keine Übernahme der gesamten GS-Beispielliste. FSP Sich positionieren verlangt eine begründete Einschätzung.',['186294'])

# Concrete didactic criteria; none are official curricular wording.
def refine(cards):
 criteria={
 'DE-125':('Das beschriebene Merkmal passt zum Arbeitsmittel und macht die Information für den Partner verständlich.','Arbeitsmittel und Merkmale werden richtig benannt; die Einschätzung des Arbeitsplatzes enthält einen nachvollziehbaren Grund.'),
 'DE-126':('Ein sachlich richtiger Handlungsschritt wird verständlich erklärt; eine einfache Rückfrage wird passend beantwortet.','Die Erklärung passt zum Arbeitsmittel; die Einschätzung des eigenen Umgangs bezieht sich mit einem Grund auf das vereinbarte Kriterium.'),
 'DE-127':('Ein Lagewort wird in der erprobten Anweisung passend verwendet; ein erster verständlicher Orientierungsversuch wird sichtbar.','Bei einer vorher nicht geübten Anordnung werden passende Lagebegriffe selbst ausgewählt; der Partner kann damit den Gegenstand eindeutig finden.'),
 'DE-128':('Eine gemeinsam erarbeitete Gesprächsregel wird benannt und an der bekannten Situation zutreffend gezeigt.','Eine bekannte Regel wird richtig wiedergegeben; das gezeigte Gesprächsverhalten entspricht dieser Regel.'),
 'DE-129':('Ein eigener Beitrag zur gemeinsamen Regelformulierung ist erkennbar; die vereinbarte Regel wird an einem bekannten Beispiel zutreffend erläutert.','Eine verständliche Gesprächsregel liegt vor; die Beurteilung des Verhaltens enthält einen passenden Grund aus der besprochenen Situation.')}
 for c in cards:
  if c['id'] in criteria:
   for g,crit in zip(c['fine_goals'],criteria[c['id']]):g['criterion']=crit+' Umfang und erlaubte Hilfen werden vorab festgelegt.'
